556	  async getGPUVendor(): Promise<string> {
557	    const msg: WorkerRequest = {
558	      kind: "getGPUVendor",
559	      uuid: crypto.randomUUID(),
560	      content: null,
561	    };
562	    return await this.getPromise<string>(msg);
563	  }
564	
565	  async getMessage(modelId?: string): Promise<string> {
566	    const msg: WorkerRequest = {
567	      kind: "getMessage",
568	      uuid: crypto.randomUUID(),
569	      content: {
570	        modelId: modelId,
571	      },
572	    };
573	    return await this.getPromise<string>(msg);
574	  }
