600	      content: null,
601	    };
602	    await this.getPromise<null>(msg);
603	    this.modelId = undefined;
604	    this.chatOpts = undefined;
605	  }
606	
607	  async resetChat(keepStats = false, modelId?: string): Promise<void> {
608	    const msg: WorkerRequest = {
609	      kind: "resetChat",
610	      uuid: crypto.randomUUID(),
611	      content: {
612	        keepStats: keepStats,
613	        modelId: modelId,
614	      },
615	    };
616	    await this.getPromise<null>(msg);
617	  }
618	
619	  async forwardTokensAndSample(
620	    inputIds: Array<number>,
621	    isPrefill: boolean,
622	    modelId?: string,
623	  ): Promise<number> {
624	    const msg: WorkerRequest = {
625	      kind: "forwardTokensAndSample",
626	      uuid: crypto.randomUUID(),
627	      content: {
628	        inputIds: inputIds,
629	        isPrefill: isPrefill,
630	        modelId: modelId,
631	      },
632	    };
633	    return await this.getPromise<number>(msg);
634	  }
635	
636	  /**
637	   * Every time the generator is called, we post a message to the worker asking it to
638	   * decode one step, and we expect to receive a message of `ChatCompletionChunk` from
639	   * the worker which we yield. The last message is `void`, meaning the generator has nothing
640	   * to yield anymore.
641	   *
642	   * @param selectedModelId: The model of whose async generator to call next() to get next chunk.
643	   *   Needed because an engine can load multiple models.
644	   *
645	   * @note ChatCompletion and Completion share the same chunk generator.
646	   */
647	  async *asyncGenerate(
648	    selectedModelId: string,
649	  ): AsyncGenerator<ChatCompletionChunk | Completion, void, void> {
650	    // Every time it gets called, sends message to worker, asking for the next chunk
651	    while (true) {
652	      const msg: WorkerRequest = {
653	        kind: "completionStreamNextChunk",
654	        uuid: crypto.randomUUID(),
655	        content: {
656	          selectedModelId: selectedModelId,
657	        } as CompletionStreamNextChunkParams,
658	      };
659	      const ret = await this.getPromise<ChatCompletionChunk>(msg);
660	      // If the worker's generator reached the end, it would return a `void`
661	      if (typeof ret !== "object") {
662	        break;
663	      }
664	      yield ret;
665	    }
666	  }
667	
668	  async chatCompletion(
669	    request: ChatCompletionRequestNonStreaming,
670	  ): Promise<ChatCompletion>;
671	  async chatCompletion(
672	    request: ChatCompletionRequestStreaming,
673	  ): Promise<AsyncIterable<ChatCompletionChunk>>;
674	  async chatCompletion(
675	    request: ChatCompletionRequestBase,
676	  ): Promise<AsyncIterable<ChatCompletionChunk> | ChatCompletion>;
677	  async chatCompletion(
678	    request: ChatCompletionRequest,
679	  ): Promise<AsyncIterable<ChatCompletionChunk> | ChatCompletion> {
680	    if (this.modelId === undefined) {
681	      throw new WorkerEngineModelNotLoadedError(this.constructor.name);
682	    }
683	    // Needed for the streaming case. Consolidate model id to specify
684	    // which model's asyncGenerator to instantiate or call next() on.
685	    // Since handler can maintain multiple generators concurrently
686	    const selectedModelId = getModelIdToUse(
687	      this.modelId ? this.modelId : [],
688	      request.model,
689	      "ChatCompletionRequest",
690	    );
691	
692	    if (request.stream) {
693	      // First let worker instantiate a generator
694	      const msg: WorkerRequest = {
695	        kind: "chatCompletionStreamInit",
696	        uuid: crypto.randomUUID(),
697	        content: {
698	          request: request,
699	          selectedModelId: selectedModelId,
700	          modelId: this.modelId,
701	          chatOpts: this.chatOpts,
702	        },
703	      };
704	      await this.getPromise<null>(msg);
705	
706	      // Then return an async chunk generator that resides on the client side
707	      return this.asyncGenerate(selectedModelId) as AsyncGenerator<
708	        ChatCompletionChunk,
709	        void,
710	        void
711	      >;
712	    }
713	
714	    // Non streaming case is more straightforward
715	    const msg: WorkerRequest = {
716	      kind: "chatCompletionNonStreaming",
717	      uuid: crypto.randomUUID(),
718	      content: {
719	        request: request,
720	        modelId: this.modelId,
721	        chatOpts: this.chatOpts,
722	      },
723	    };
724	    return await this.getPromise<ChatCompletion>(msg);
725	  }
726	
727	  async completion(
728	    request: CompletionCreateParamsNonStreaming,
729	  ): Promise<Completion>;
730	  async completion(
731	    request: CompletionCreateParamsStreaming,
732	  ): Promise<AsyncIterable<Completion>>;
